DROP PROCEDURE IF EXISTS `ms_naxx_cache_restore_20261007`;
DELIMITER $$
CREATE PROCEDURE `ms_naxx_cache_restore_20261007`()
BEGIN
    DECLARE `normal_naxx` INT UNSIGNED DEFAULT 0;
    DECLARE `heroic_naxx` INT UNSIGNED DEFAULT 0;
    DECLARE `mythic_naxx` INT UNSIGNED DEFAULT 0;
    DECLARE `mythic_aq40` INT UNSIGNED DEFAULT 0;
    DECLARE `dungeon_21_30` INT UNSIGNED DEFAULT 0;
    DECLARE `dungeon_31_40` INT UNSIGNED DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    IF (SELECT COUNT(*) FROM `information_schema`.`TABLES`
        WHERE `TABLE_SCHEMA` = DATABASE() AND `TABLE_NAME` IN ('item_loot_template', 'reference_loot_template')
            AND `ENGINE` = 'InnoDB') <> 2 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Naxx caches: InnoDB loot tables required';
    END IF;
    START TRANSACTION;
    IF (SELECT COUNT(*) FROM `tmp_ms_naxx_candidate`) <> 12726 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Naxx caches: expected 12726 candidate assignments';
    END IF;
    -- One scan: MySQL cannot reopen a temporary table twice in one statement.
    SELECT COUNT(CASE WHEN `Pool` = 9003701 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003702 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003703 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003704 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003705 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003706 THEN 1 END)
    INTO `normal_naxx`, `heroic_naxx`, `mythic_naxx`, `mythic_aq40`,
        `dungeon_21_30`, `dungeon_31_40`
    FROM `tmp_ms_naxx_candidate`;
    IF `normal_naxx` <> 129 OR `heroic_naxx` <> 109 OR `mythic_naxx` <> 129
        OR `mythic_aq40` <> 139 OR `dungeon_21_30` <> 6110 OR `dungeon_31_40` <> 6110 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Naxx caches: candidate family count mismatch';
    END IF;
    IF (SELECT COUNT(*) FROM `item_template`
        WHERE `entry` IN (1278079, 1278081, 1278083) AND (`Flags` & 4) <> 0 AND `ScriptName` = '') <> 3 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Naxx caches: missing scriptless HAS_LOOT containers';
    END IF;
    IF EXISTS (
        SELECT 1 FROM `tmp_ms_naxx_candidate` AS `c`
        LEFT JOIN `item_template` AS `i` ON `i`.`entry` = `c`.`Item`
        WHERE `i`.`entry` IS NULL OR BINARY `i`.`name` <> BINARY `c`.`Name`
            OR `i`.`class` <> `c`.`Class` OR `i`.`subclass` <> `c`.`Subclass`
            OR `i`.`InventoryType` <> `c`.`InventoryType` OR `i`.`Quality` <> `c`.`Quality`
            OR `i`.`RequiredLevel` <> `c`.`RequiredLevel` OR `i`.`displayid` <> `c`.`DisplayId`
            OR `i`.`ItemLevel` <> `c`.`ItemLevel`
            OR BINARY `i`.`description` <> BINARY `c`.`Description`
            OR `i`.`RequiredLevel` > 60 OR `i`.`class` NOT IN (2, 4) OR `i`.`InventoryType` = 0
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Naxx caches: candidate metadata mismatch';
    END IF;
    IF EXISTS (SELECT 1 FROM `reference_loot_template`
        WHERE `Entry` IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706)
            AND `Comment` <> 'MS Classic Naxx cache family pool')
        OR EXISTS (SELECT 1 FROM `reference_loot_template`
            WHERE ABS(`Reference`) IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706))
        OR EXISTS (SELECT 1 FROM `item_loot_template`
            WHERE ABS(`Reference`) IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706)
                AND `Entry` NOT IN (1278079, 1278081, 1278083)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Naxx caches: reserved reference namespace collision';
    END IF;
    IF EXISTS (SELECT 1 FROM `creature_loot_template`
            WHERE ABS(`Reference`) IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706))
        OR EXISTS (SELECT 1 FROM `disenchant_loot_template`
            WHERE ABS(`Reference`) IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706))
        OR EXISTS (SELECT 1 FROM `fishing_loot_template`
            WHERE ABS(`Reference`) IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706))
        OR EXISTS (SELECT 1 FROM `gameobject_loot_template`
            WHERE ABS(`Reference`) IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706))
        OR EXISTS (SELECT 1 FROM `mail_loot_template`
            WHERE ABS(`Reference`) IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706))
        OR EXISTS (SELECT 1 FROM `milling_loot_template`
            WHERE ABS(`Reference`) IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706))
        OR EXISTS (SELECT 1 FROM `pickpocketing_loot_template`
            WHERE ABS(`Reference`) IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706))
        OR EXISTS (SELECT 1 FROM `prospecting_loot_template`
            WHERE ABS(`Reference`) IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706))
        OR EXISTS (SELECT 1 FROM `skinning_loot_template`
            WHERE ABS(`Reference`) IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706))
        OR EXISTS (SELECT 1 FROM `spell_loot_template`
            WHERE ABS(`Reference`) IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706))
        OR EXISTS (SELECT 1 FROM `player_loot_template`
            WHERE ABS(`Reference`) IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Naxx caches: references used by another loot store';
    END IF;
    IF EXISTS (SELECT 1 FROM `conditions`
        WHERE (`SourceTypeOrReferenceId` = 10
            AND `SourceGroup` IN (9003701,9003702,9003703,9003704,9003705,9003706))
            OR (`SourceTypeOrReferenceId` = 5 AND `SourceGroup` IN (1278079,1278081,1278083))) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Naxx caches: existing loot conditions require review';
    END IF;
    DELETE FROM `reference_loot_template`
    WHERE `Entry` IN (9003701, 9003702, 9003703, 9003704, 9003705, 9003706);
    INSERT INTO `reference_loot_template`
        (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`,
            `MinCount`, `MaxCount`, `Comment`)
    SELECT `Pool`, `Item`, 0, 0, 0, 1, 1, 1, 1, 'MS Classic Naxx cache family pool'
    FROM `tmp_ms_naxx_candidate`;
    DELETE FROM `item_loot_template` WHERE `Entry` IN (1278079, 1278081, 1278083);
    INSERT INTO `item_loot_template`
        (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`,
            `MinCount`, `MaxCount`, `Comment`)
    VALUES
    (1278079, 1, 9003704, 100, 0, 1, 1, 1, 1, 'MS Naxx: guaranteed Mythic AQ40'),
    (1278079, 2, 9003701, 100, 0, 1, 2, 1, 1, 'MS Naxx: guaranteed Normal Naxx'),
    (1278079, 3, 9003705, 10, 0, 1, 3, 1, 1, 'MS Naxx: optional Mythic 21-30 Dungeon'),
    (1278081, 1, 9003701, 100, 0, 1, 1, 1, 1, 'MS Naxx: guaranteed Normal Naxx'),
    (1278081, 2, 9003702, 10, 0, 1, 2, 1, 1, 'MS Naxx: optional Heroic Naxx'),
    (1278081, 3, 9003706, 10, 0, 1, 3, 1, 1, 'MS Naxx: optional Mythic 31-40 Dungeon'),
    (1278083, 1, 9003702, 100, 0, 1, 1, 1, 1, 'MS Naxx: guaranteed Heroic Naxx'),
    (1278083, 2, 9003703, 10, 0, 1, 2, 1, 1, 'MS Naxx: optional Mythic Naxx'),
    (1278083, 3, 9003706, 10, 0, 1, 3, 1, 1, 'MS Naxx: optional Mythic 31-40 Dungeon');
    IF (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278079) <> 3
        OR (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278081) <> 3
        OR (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278083) <> 3
        OR (SELECT COUNT(*) FROM `reference_loot_template`
            WHERE `Entry` IN (9003701,9003702,9003703,9003704,9003705,9003706)) <> 12726 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Naxx caches: post-write row count mismatch';
    END IF;
    COMMIT;
END$$
DELIMITER ;
CALL `ms_naxx_cache_restore_20261007`();
DROP PROCEDURE `ms_naxx_cache_restore_20261007`;

SELECT `Entry`, `Reference`, `Chance`, `GroupId`, `MinCount`, `MaxCount`
FROM `item_loot_template` WHERE `Entry` IN (1278079,1278081,1278083) ORDER BY `Entry`, `Item`;
SELECT `Entry`, COUNT(*) AS `Candidates`
FROM `reference_loot_template`
    WHERE `Entry` IN (9003701,9003702,9003703,9003704,9003705,9003706)
GROUP BY `Entry`;
DROP TEMPORARY TABLE `tmp_ms_naxx_candidate`;
